mapper.select:
/*selectMasterCmClSalesTaxsheetUploadingCreationList*/
SELECT DECODE(GR.AR_BILL_FLAG,NULL,'오류','Y','생성','N','미생성') AS IS_CREATE , TM.SEQ AS TAX_SERIAL , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'TX01' AND CODE = TM.KEP_IRS) AS KEP_IRS_NAME , TM.IRS_NO AS BUYER_IRS_NO , DECODE(IR.IRS_NO,NULL,CM.COM_NAME_LOC,IR.IRS_NAME) AS BUYER_NAME , TM.DEPT_CODE AS KEP_DEPT , TM.GR_DATE AS GR_DATE , DECODE(GR.BUYER ,'KRHONG0020',ROUND((TM.GR_AMT/1.1)),TM.GR_AMT) AS GR_AMT , TM.PO_NO , TM.GR_NO , TM.GR_SEQ , TM.BUYER , (SELECT IRS_NO FROM KEPTIRSN WHERE 1=1 AND COM_CODE = 'KRKORE0001' AND SITE = TM.SITE AND IRS_NO = TM.KEP_IRS) AS KEP_IRS_NO , TM.SITE AS SITE_GUBUN_CODE , '' AS BUSINESS_TYPE , '' AS CL_MON , F_GET_CREDIT_LIMIT_STTS(TM.BUYER,'','','2') AS CREDIT_LIMIT_FLAG FROM KEPTEXUP TM /* 매출세금계산서 업로드 임시 테이블 */ , ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , KEPTIRSN IR /* 구매사 사업자정보 */ WHERE 1=1 AND TM.BUYER = GR.BUYER(+) AND TM.GR_NO = GR.GR_NO(+) AND TM.GR_SEQ = GR.GR_SEQ(+) AND TM.BUYER = CM.COM_CODE AND TM.SITE = IR.SITE(+) AND TM.IRS_NO = IR.IRS_NO(+) AND TM.BUYER = IR.COM_CODE(+) AND GR.STATUS(+) <> 'D' AND TM.SITE = 'KA'
AND( TM.BUYER = #{st_buyer_code} OR TM.BUYER = 'KRDOOS0004')
AND( TM.BUYER = #{st_buyer_code} OR TM.BUYER = 'KRISUC0005' OR TM.BUYER = 'KRISUC0006')
AND( TM.BUYER = #{st_buyer_code} OR TM.BUYER = 'KRCOWA0005' OR TM.BUYER = 'KRCOWA0006')
AND TM.BUYER = #{st_buyer_code}
AND DECODE(GR.AR_BILL_FLAG,NULL,'E',GR.AR_BILL_FLAG) = #{st_status}
ORDER BY TM.SEQ , GR_NO , GR_SEQ

/*"selectMasterCmClSalesTaxsheetUploadingCreationList_Check"*/

		SELECT 
		    DECODE(COUNT(*), 0, 'N', 'Y') AS CHECK_YN
		FROM 
		    KEPTEXUP /* 매출세금계산서 업로드 임시 테이블 */
		WHERE 1=1
		AND BUYER = #{BUYER}
		AND GR_NO = #{GR_NO}
		AND GR_SEQ = #{GR_SEQ}

mapper.update:
/*insertMasterCmClSalesTaxsheetUploadingCreation*/

		INSERT INTO KEPTEXUP /* 매출세금계산서 업로드 임시 테이블 */
		( 
		    BUYER 
		  , GR_NO 
		  , GR_SEQ 
		  , SEQ 
		  , KEP_IRS 
		  , SITE 
		  , IRS_NO 
		  , PO_NO 
		  , DEPT_CODE 
		  , GR_DATE 
		  , GR_AMT 
		  , ADD_USER_ID 
		)
		VALUES
		( 
		    #{BUYER}
		  , #{GR_NO}
		  , LPAD(#{GR_SEQ}, 6, 0)
		  , #{TAX_SERIAL}
		  , #{KEP_IRS_NO} 
		  , #{SITE_GUBUN_CODE}
		  , #{BUYER_IRS_NO}
		  , #{PO_NO}
		  , #{KEP_DEPT}
		  , #{GR_DATE}
		  , #{GR_AMT}
		  , #{st_user_id}
		)

/*updateMasterCmClSalesTaxsheetUploadingCreation_KEPTEXUP*/

		UPDATE 
		    KEPTEXUP /* 매출세금계산서 업로드 임시 테이블 */
		SET 
		    TAX_BILL_NO = #{order_no}
		  , IRS_NO = #{BUYER_IRS_NO}
		  , DEPT_CODE = #{KEP_DEPT}
		WHERE 1=1
		AND BUYER  = #{BUYER}
		AND GR_NO  = #{GR_NO}
		AND GR_SEQ = #{GR_SEQ}

/*deleteMasterCmClSalesTaxsheetUploadingCreation*/

		DELETE 
			KEPTEXUP /* 매출세금계산서 업로드 임시 테이블 */ 
		WHERE 1=1 
		AND BUYER = #{BUYER} 
		AND GR_NO = #{GR_NO} 
		AND GR_SEQ = #{GR_SEQ}

/*deleteMasterCmClSalesTaxsheetUploadingCreation_KEPTEXUP*/
DELETE KEPTEXUP /* 매출세금계산서 업로드 임시 테이블 */ WHERE 1=1 AND SITE = 'KA' AND TAX_BILL_NO IS NOT NULL
AND (BUYER = #{st_buyer_code} OR BUYER = 'KRDOOS0004')
AND (BUYER = #{st_buyer_code} OR BUYER = 'KRISUC0005' OR BUYER = 'KRISUC0006')
AND (BUYER = #{st_buyer_code} OR BUYER = 'KRCOWA0001' OR BUYER = 'KRCOWA0006' OR BUYER = 'KRCOWA0005')
AND BUYER = #{st_buyer_code}
